function crearDoble() {
  const raiz = {};
  raiz.siguiente = raiz;
  raiz.anterior = raiz;
  return raiz;
}

function ponerAntes(destino, valor) {
  const nodo = { valor, anterior: destino.anterior, siguiente: destino };
  nodo.anterior.siguiente = nodo;
  destino.anterior = nodo;
  return nodo;
}

function sacarDoble(nodo) {
  nodo.anterior.siguiente = nodo.siguiente;
  nodo.siguiente.anterior = nodo.anterior;
}

function crearLRU(capacidad) {
  const raiz = crearDoble();
  const indice = new Map();
  function promover(nodo) {
    sacarDoble(nodo);
    indice.set(nodo.valor.clave, ponerAntes(raiz, nodo.valor));
  }
  return {
    leer(clave) {
      const nodo = indice.get(clave);
      if (!nodo) return { acierto: false, valor: null };
      promover(nodo);
      return { acierto: true, valor: nodo.valor.valor };
    },
    guardar(clave, valor) {
      if (capacidad === 0) return;
      const nodo = indice.get(clave);
      if (nodo) {
        nodo.valor.valor = valor;
        promover(nodo);
        return;
      }
      if (indice.size === capacidad) {
        const expulsado = raiz.siguiente;
        sacarDoble(expulsado);
        indice.delete(expulsado.valor.clave);
      }
      indice.set(clave, ponerAntes(raiz, { clave, valor }));
    },
    orden() {
      const claves = [];
      for (let nodo = raiz.siguiente; nodo !== raiz; nodo = nodo.siguiente)
        claves.push(nodo.valor.clave);
      return claves;
    },
  };
}

function tablaPrefijos(patron) {
  const pi = Array(patron.length).fill(0);
  let largo = 0;
  for (let i = 1; i < patron.length; i++) {
    while (largo && patron[i] !== patron[largo]) largo = pi[largo - 1];
    if (patron[i] === patron[largo]) largo++;
    pi[i] = largo;
  }
  return pi;
}

function buscarKMP(texto, patron) {
  if (!patron.length)
    return Array.from({ length: texto.length + 1 }, (_, i) => i);
  const pi = tablaPrefijos(patron);
  const indices = [];
  let largo = 0;
  for (let i = 0; i < texto.length; i++) {
    while (largo && texto[i] !== patron[largo]) largo = pi[largo - 1];
    if (texto[i] === patron[largo]) largo++;
    if (largo === patron.length) {
      indices.push(i - patron.length + 1);
      largo = pi[largo - 1];
    }
  }
  return indices;
}

function canonizarNombre(texto) {
  return texto.trim().toLowerCase().normalize("NFC");
}

function indiceDeNombres(estaciones) {
  const porNombre = new Map();
  for (const [codigo, nombre] of estaciones) {
    const clave = canonizarNombre(nombre);
    if (!porNombre.has(clave)) porNombre.set(clave, []);
    porNombre.get(clave).push(codigo);
  }
  return porNombre;
}

function catalogoTesla(estaciones, acciones, capacidad) {
  const nombres = indiceDeNombres(estaciones);
  const cache = crearLRU(capacidad);
  const historia = [];
  const respuestas = [];
  for (const [modo, consulta] of acciones) {
    if (modo === "deshacer") {
      respuestas.push(historia.pop() ?? null);
      continue;
    }
    const clave = canonizarNombre(consulta);
    const claveCache = JSON.stringify([modo, clave]);
    const previa = cache.leer(claveCache);
    let codigos = previa.valor;
    if (!previa.acierto) {
      if (clave === "") codigos = [];
      else if (modo === "exacta") codigos = nombres.get(clave) ?? [];
      else {
        const aceptados = new Set();
        for (const nombre of nombres.keys()) {
          if (buscarKMP(nombre, clave).length) aceptados.add(nombre);
        }
        codigos = estaciones
          .filter(([, nombre]) => aceptados.has(canonizarNombre(nombre)))
          .map(([codigo]) => codigo);
      }
      cache.guardar(claveCache, codigos);
    }
    historia.push({ modo, clave, codigos });
    respuestas.push({ acierto: previa.acierto, codigos });
  }
  return { respuestas, historia };
}

function limiteHorario(datos, hora, despues = false) {
  let inicio = 0;
  let fin = datos.length;
  while (inicio < fin) {
    const medio = inicio + Math.floor((fin - inicio) / 2);
    const minuto = datos[medio];
    if (minuto < hora || (despues && minuto === hora)) inicio = medio + 1;
    else fin = medio;
  }
  return inicio;
}

function aparicionesHorario(datos, hora) {
  const primera = limiteHorario(datos, hora);
  const fin = limiteHorario(datos, hora, true);
  return primera === fin ? null : [primera, fin - 1];
}

function consultarHorario(datos, hora) {
  const apariciones = aparicionesHorario(datos, hora);
  const siguiente = datos[limiteHorario(datos, hora)] ?? null;
  return { apariciones, siguiente };
}

function primerVerdadero(inicio, fin, cumple) {
  while (inicio < fin) {
    const medio = inicio + Math.floor((fin - inicio) / 2);
    if (cumple(medio)) fin = medio;
    else inicio = medio + 1;
  }
  return inicio;
}
function inicioAutorizado(estados) {
  return primerVerdadero(0, estados.length, (i) => estados[i]);
}

function viajesPara(cargas, capacidad) {
  let viajes = 0;
  let ocupado = 0;
  for (const peso of cargas) {
    if (peso > capacidad) return null;
    if (!viajes || ocupado + peso > capacidad) {
      viajes++;
      ocupado = 0;
    }
    ocupado += peso;
  }
  return viajes;
}

function capacidadMinima(cargas, maximoViajes) {
  let mayor = 0;
  let suma = 0;
  for (const peso of cargas) {
    mayor = Math.max(mayor, peso);
    suma += peso;
  }
  return primerVerdadero(mayor, suma, (capacidad) => {
    const viajes = viajesPara(cargas, capacidad);
    return viajes !== null && viajes <= maximoViajes;
  });
}

function porInsercion(registros) {
  const salida = registros.slice();
  for (let i = 1; i < salida.length; i++) {
    const nuevo = salida[i];
    let hueco = i;
    while (hueco > 0 && salida[hueco - 1][0] > nuevo[0]) {
      salida[hueco] = salida[hueco - 1];
      hueco--;
    }
    salida[hueco] = nuevo;
  }
  return salida;
}

function porSeleccion(registros) {
  const salida = registros.slice();
  for (let i = 0; i < salida.length; i++) {
    let menor = i;
    for (let j = i + 1; j < salida.length; j++) {
      if (salida[j][0] < salida[menor][0]) menor = j;
    }
    [salida[i], salida[menor]] = [salida[menor], salida[i]];
  }
  return salida;
}
function porBurbuja(registros) {
  const salida = registros.slice();
  for (let fin = salida.length - 1; fin > 0; fin--) {
    let huboCambio = false;
    for (let i = 0; i < fin; i++) {
      if (salida[i][0] > salida[i + 1][0]) {
        [salida[i], salida[i + 1]] = [salida[i + 1], salida[i]];
        huboCambio = true;
      }
    }
    if (!huboCambio) break;
  }
  return salida;
}
function contrastarCuadraticos(registros) {
  return { seleccion: porSeleccion(registros), burbuja: porBurbuja(registros) };
}

function prepararListado(registros) {
  const insercion = porInsercion(registros);
  const { seleccion, burbuja } = contrastarCuadraticos(registros);
  const empatesConservados = insercion.every(
    (registro, i) => registro[1] === burbuja[i][1],
  );
  return { insercion, seleccion, burbuja, empatesConservados };
}

function mezclarHorarios(a, b) {
  const salida = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i][0] <= b[j][0]) salida.push(a[i++]);
    else salida.push(b[j++]);
  }
  for (; i < a.length; i++) salida.push(a[i]);
  for (; j < b.length; j++) salida.push(b[j]);
  return salida;
}

function ordenarMezcla(registros) {
  if (registros.length < 2) return registros.slice();
  const medio = Math.floor(registros.length / 2);
  const izquierda = ordenarMezcla(registros.slice(0, medio));
  const derecha = ordenarMezcla(registros.slice(medio));
  return mezclarHorarios(izquierda, derecha);
}

function consultaOrdenada(registros, minuto) {
  const horario = ordenarMezcla(registros);
  const consulta = consultarHorario(
    horario.map((registro) => registro[0]),
    minuto,
  );
  return { horario, consulta };
}

function partirTres(datos, inicio, fin, pivote) {
  let menor = inicio;
  let i = inicio;
  let mayor = fin;
  while (i < mayor) {
    if (datos[i] < pivote) {
      [datos[menor], datos[i]] = [datos[i], datos[menor]];
      menor++;
      i++;
    } else if (datos[i] > pivote) {
      mayor--;
      [datos[i], datos[mayor]] = [datos[mayor], datos[i]];
    } else i++;
  }
  return [menor, mayor];
}
function separarClaves(datos, pivote) {
  const copia = datos.slice();
  const [menor, mayor] = partirTres(copia, 0, copia.length, pivote);
  return [copia.slice(0, menor), copia.slice(menor, mayor), copia.slice(mayor)];
}

function ordenarRapido(datos, fraccion) {
  const copia = datos.slice();
  const pendientes = [[0, copia.length]];
  while (pendientes.length) {
    const [inicio, fin] = pendientes.pop();
    if (fin - inicio < 2) continue;
    const muestra = fraccion === undefined ? Math.random() : fraccion;
    const pivote = copia[inicio + Math.floor(muestra * (fin - inicio))];
    const [menor, mayor] = partirTres(copia, inicio, fin, pivote);
    pendientes.push([inicio, menor], [mayor, fin]);
  }
  return copia;
}

function brechasHorarias(datos, fraccion) {
  const orden = ordenarRapido(datos, fraccion);
  const brechas = orden.slice(1).map((minuto, i) => minuto - orden[i]);
  return { orden, brechas };
}

